#!/usr/bin/env bash
# Release R26 - task 99 (D-1472). The diff travels xz+base64 behind a sha256 guard.
set -euo pipefail
echo '' | base64 -d | xz -d > /tmp/r26.diff
echo "98428b501fa71d9df3f17c23472dc5c0286ce0425fb9b9e16e668e0e2cc02f94  /tmp/r26.diff" | sha256sum -c -
git apply --index /tmp/r26.diff
